def dv(no, ek=''):
  o = OZ.get(no, {}); r = str(o.get('rapor') or '').replace('/Users/ramazanakkocan/Desktop/ByGatech/projeler/jewellery', KOK)
  t = (f"⚠ DEVIR NOTU (orkestrator 28.09 11:35): bu paket 25-28.09 arasinda defalarca KESILDI (uygulama yeniden baslamalari, Docker cokmesi, ag kesintisi); 28.09 11:15 kosumunda ajanlar kurucunun baska konudaki mesaji yuzunden kod YAZMADAN dondu — o kosum SAYILMAZ. Gecerli son uygulayici durumu: {o.get('uyg_durum')}; raporu: {r}. "
       "AGACTAKI ISI KORU — YENIDEN YAZMA. ONCE raporu oku ve 'git status --porcelain | grep -v -E \"/(bin|obj)/\"' + ilgili dosyalarda 'git diff' ile agaci gor; eksikleri tamamla; kabul olcumlerini GUNCEL agacta (25.09 18:05 'aksam-1810' yayinina giren tum paketlerle birlikte) YENIDEN kos ve raporu guncelle. "
       "Agacta yarim mutasyon kalmis olabilir: /private/tmp/kuyumcu-serit ve raporundaki yedek yollarini kontrol et (yeniden baslatmada /tmp silindi — yedek yoksa ilgili testler yesil mi, ona bak). ")
  if o.get('acik'): t += "Uygulayicinin acik kalanlari: " + ' | '.join(str(x)[:300] for x in o['acik']) + ". "
  d = o.get('son_dogrulama')
  if d and d.get('bulgular'): t += f"SON DOGRULAMA ({d.get('karar')}) bulgulari — ONCE BUNLARI KAPAT: " + ' | '.join(d['bulgular']) + ". "
  if o.get('son_hakem_kritik'): t += "SON HAKEM KRITIK celiskileri: " + ' | '.join(o['son_hakem_kritik']) + ". "
  return devir(no, t + ek)
